            accept: [['tied|linked|depend|fixed|set by|follow|match|fit|bound'], ['parent|work|job'], ['bus|transport|timetable|hard to change|difficult to change']],
            reject: [{ re: '\\bno school\\b|\\bever\\b|anywhere', hint: 'Too absolute: it cannot be shown.' },
              { re: 'hours of sleep|eight and ten', hint: 'A figure you cannot check, and it is not a second cause.' },
              { re: 'traffic|between seven', hint: 'A claim you cannot check, and traffic does not explain the early start.' },
              { re: 'start times is\\b', hint: '"Start times" is plural: check the verb.' }],
